import sys,json,ast,operator as op
args=json.load(sys.stdin)
OPS={ast.Add:op.add,ast.Sub:op.sub,ast.Mult:op.mul,ast.Div:op.truediv,ast.Pow:op.pow,ast.Mod:op.mod,ast.USub:op.neg,ast.UAdd:op.pos}
def ev(n):
    if isinstance(n,ast.Constant) and isinstance(n.value,(int,float)): return n.value
    if isinstance(n,ast.BinOp) and type(n.op) in OPS: return OPS[type(n.op)](ev(n.left),ev(n.right))
    if isinstance(n,ast.UnaryOp) and type(n.op) in OPS: return OPS[type(n.op)](ev(n.operand))
    raise ValueError('only arithmetic allowed')
expr=str(args.get('expression',''))
print(json.dumps({'expression':expr,'result':ev(ast.parse(expr,mode='eval').body)}))
